/// Implementation of `meshgrid` satisfying the given Verus specification.
fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    // Precondition (enforced by the verifier spec):
    //   x.len() > 0 && y.len() > 0

    let nx = x.len();
    let ny = y.len();

    // Prepare the output matrices with the correct number of rows
    let mut X: Vec<Vec<f32>> = Vec::with_capacity(ny);
    let mut Y: Vec<Vec<f32>> = Vec::with_capacity(ny);

    // For each element y[i], build one row in X (a clone of x)
    // and one row in Y (all entries equal to y[i]).
    let mut i: usize = 0;
    while i < ny {
        // Clone the entire x‐vector for the i‐th row of X
        X.push(x.clone());

        // Build the i‐th row of Y by repeating y[i] nx times
        let mut row_y: Vec<f32> = Vec::with_capacity(nx);
        let yi = y[i];
        let mut j: usize = 0;
        while j < nx {
            row_y.push(yi);
            j += 1;
        }
        Y.push(row_y);

        i += 1;
    }

    // Return the pair of matrices
    (X, Y)
}